interface.definition:
a!localVariables(
  local!selectedorg:#"_a-0000eef8-4604-8000-9e54-011c48011c48_1092772"(parentorgId: ri!orgid, isActive: true()),
  local!childid:if(a!isNullOrEmpty(local!selectedorg),-1,index(local!selectedorg,#"urn:appian:record-field:v1:28808922-2be4-47a6-a7b6-33b1b5da8c2d/0c02b78a-3116-4b9c-b8d4-117c5519f675",null())),

  #"SYSTEM_SYSRULES_formLayout_v2"(
    contents: {
      #"_a-0000eef8-4604-8000-9e54-011c48011c48_1124164"(
        selected: ri!isselected,
        parentid: ri!orgid,
        isselectable: true(),
        childids: local!childid
      ),
    },
    buttons: #"SYSTEM_SYSRULES_ButtonLayout"(
      primaryButtons: {
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "Submit",
          submit: true,
          saveInto: {
            a!save(ri!button,#"_a-0000eeda-0177-8000-9e52-011c48011c48_1085463")
          },
          loadingIndicator: true,
          style: "SOLID"
        )
      },
      secondaryButtons: {
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "Cancel",
          value: true,
          saveInto: {
            a!save(ri!button,#"_a-0000eeda-0177-8000-9e52-011c48011c48_1085469")
          },
          validate: false,
          submit: true,
          style: "OUTLINE"
        )
      }
    ),
    contentsWidth: "WIDE"
  )
)
